g=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
from collections import deque
R,C=len(g),len(g[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if g[r][c]==0 and (r,c) not in seen:
   q=deque([(r,c)]); seen.add((r,c)); comp=[]
   while q:
    x,y=q.popleft(); comp.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<R and 0<=ny<C and g[nx][ny]==0 and (nx,ny) not in seen: seen.add((nx,ny));q.append((nx,ny))
   comps.append(comp)
[(len(x),x) for x in comps]
